"""Invoice totals and rendering; see SPEC.md sections 2 and 3."""

_DISCOUNT_PERCENT = {"TENOFF": 10}


def _div_round_half_up(n: int, d: int) -> int:
    """n / d rounded to nearest, ties away from zero (d > 0)."""
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def _div_round_half_even(n: int, d: int) -> int:
    """n / d rounded to nearest, ties to even (d > 0)."""
    q, r = divmod(n, d)  # floor division: 0 <= r < d
    if 2 * r > d or (2 * r == d and q % 2 == 1):
        q += 1
    return q


def invoice_total(lines, tax_rate_bp, discount_code=None):
    subtotal = 0
    for quantity, unit_cents in lines:
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 1:
            raise ValueError(f"quantity must be an int >= 1: {quantity!r}")
        subtotal += quantity * unit_cents

    if discount_code is None:
        discount = 0
    elif discount_code in _DISCOUNT_PERCENT:
        discount = _div_round_half_up(subtotal * _DISCOUNT_PERCENT[discount_code], 100)
    else:
        raise ValueError(f"unknown discount code: {discount_code!r}")

    taxable = subtotal - discount
    tax = _div_round_half_even(taxable * tax_rate_bp, 10000)
    return taxable + tax


def render_tags(tags):
    return ", ".join(sorted(tags))
EOF
